BEGIN;
SELECT plan(16);
CREATE TEMP TABLE history AS SELECT to_jsonb(m) AS body FROM public.basic_care_memberships m WHERE plant_id='15800000-0000-4000-8000-000000000201';
SELECT throws_ok($q$SELECT public.execute_basic_care_command('15800000-0000-4000-8000-000000000001','16100000-0000-4000-8000-000000000101','free_care.select','{"selected_plant_ids":[]}'::jsonb)$q$, '22023', 'FREE_SELECTION_RETIRED', 'New selection rejected');
SELECT ok((SELECT public.execute_basic_care_command('15800000-0000-4000-8000-000000000001','15800000-0000-4000-8000-000000000821','free_care.select','{"selected_plant_ids":[]}'::jsonb)='{"legacy_selection":true}'::jsonb), 'Historical selection exact replay retained');
SELECT throws_ok($q$SELECT public.execute_basic_care_command('15800000-0000-4000-8000-000000000001','15800000-0000-4000-8000-000000000821','free_care.select','{"selected_plant_ids":["15800000-0000-4000-8000-000000000201"]}'::jsonb)$q$, '23505', 'operation_payload_mismatch', 'Historical replay hash mismatch conflicts');
SELECT throws_ok($q$SELECT public.execute_basic_care_command('15800000-0000-4000-8000-000000000001','15800000-0000-4000-8000-000000000821','basic_care.enable','{"selected_plant_ids":[]}'::jsonb)$q$, '23505', 'operation_payload_mismatch', 'Replay command mismatch conflicts');
SELECT lives_ok($q$SELECT public.reconcile_owner_basic_care('15800000-0000-4000-8000-000000000001')$q$, 'Reconcile still works');
SELECT ok((SELECT to_jsonb(m)=(SELECT body FROM history) FROM public.basic_care_memberships m WHERE plant_id='15800000-0000-4000-8000-000000000201'), 'Reconcile preserves historical membership and slot');
SELECT ok((SELECT NOT (public.reconcile_owner_basic_care('15800000-0000-4000-8000-000000000001') ? 'free_selection_explicit') AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(public.reconcile_owner_basic_care('15800000-0000-4000-8000-000000000001')->'memberships') m WHERE m ? 'free_slot')), 'New basic-care state excludes retired keys');
SELECT ok((SELECT NOT (public.fetch_sync_delta('15800000-0000-4000-8000-000000000001')->'profile' ?| ARRAY['free_selection_explicit','free_selection_revision'])), 'New profile delta excludes selection keys');
SELECT ok((SELECT NOT EXISTS(SELECT 1 FROM public.owner_sync_entries WHERE owner_id='15800000-0000-4000-8000-000000000001' AND entity_type='basic_care_memberships' AND data ?| ARRAY['free_slot','selection_revision'])), 'Membership delta excludes retired keys');
SELECT ok((SELECT public.compute_next_available_step('15800000-0000-4000-8000-000000000001','15800000-0000-4000-8000-000000000201','care',false,'available')->>'next_available_step'<>'select_free_plants'), 'Next step never selects Free triple');
SELECT lives_ok($q$SELECT public.execute_basic_care_command('15800000-0000-4000-8000-000000000001','16100000-0000-4000-8000-000000000103','basic_care.enable','{"plant_id":"15800000-0000-4000-8000-000000000203"}'::jsonb)$q$, 'Enable uses current receipt schema');
SELECT lives_ok($q$SELECT public.execute_basic_care_command('15800000-0000-4000-8000-000000000001','16100000-0000-4000-8000-000000000103','basic_care.enable','{"plant_id":"15800000-0000-4000-8000-000000000203"}'::jsonb)$q$, 'Basic enable exact retry succeeds');
SELECT ok((SELECT free_slot IS NULL FROM public.basic_care_memberships WHERE plant_id='15800000-0000-4000-8000-000000000203'), 'Enable does not assign a slot');
SELECT throws_ok($q$SELECT public.execute_basic_care_command('15800000-0000-4000-8000-000000000002','16100000-0000-4000-8000-000000000104','basic_care.enable','{"plant_id":"15800000-0000-4000-8000-000000000201"}'::jsonb)$q$, 'P0002', 'plant_not_found', 'Other owner cannot enable membership');
SELECT ok((SELECT has_function_privilege('service_role','public.execute_basic_care_command(uuid,uuid,text,jsonb)','EXECUTE') AND NOT has_function_privilege('anon','public.execute_basic_care_command(uuid,uuid,text,jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','public.execute_basic_care_command(uuid,uuid,text,jsonb)','EXECUTE')), 'Basic care service-only grants retained');
SELECT ok((SELECT count(*)=1 FROM public.basic_care_memberships WHERE owner_id='15800000-0000-4000-8000-000000000001' AND free_slot IS NOT NULL), 'No implicit selection of first three');
SELECT * FROM finish();
ROLLBACK;
